	expected := "missing required flag: --from"
	if err.Error() != expected {
		t.Errorf("expected error %q, got %q", expected, err.Error())
	}
}

func TestListCommand_ShowsUnreadMessages(t *testing.T) {
	db := testutil.NewTestDB(t)
	agent := "mike"

	msg1 := csuite.CsuiteInboxMessage{ID: uuid.New(), FromAgent: "alice", ToAgent: agent, Subject: "Sub1", Archived: false}
	msg2 := csuite.CsuiteInboxMessage{ID: uuid.New(), FromAgent: "bob", ToAgent: agent, Subject: "Sub2", Archived: false}
	msg3 := csuite.CsuiteInboxMessage{ID: uuid.New(), FromAgent: "charlie", ToAgent: agent, Subject: "Sub3", Archived: true}

	if err := db.Create(&msg1).Error; err != nil {
		t.Fatal(err)
	}
	if err := db.Create(&msg2).Error; err != nil {
		t.Fatal(err)
	}
