	r, w, _ := os.Pipe()
	os.Stdout = w

	args := []string{"list", "--agent", agent}
	err := run(context.Background(), args, db)
	if err != nil {
		t.Fatalf("run failed: %v", err)
	}

	w.Close()
	os.Stdout = oldStdout

	var buf bytes.Buffer
	_, _ = io.Copy(&buf, r)
