func handleSend(args []string, db *gorm.DB) error {
	var from, to, subject, priority, msgType, body string
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--from":
			if i+1 < len(args) {
				from = args[i+1]
				i++
			}
		case "--to":
			if i+1 < len(args) {
				to = args[i+1]
				i++
			}
		case "--subject":
			if i+1 < len(args) {
				subject = args[i+1]
				i++
			}
		case "--priority":
			if i+1 < len(args) {
				priority = args[i+1]
				i++
			}
		case "--type":
			if i+1 < len(args) {
				msgType = args[i+1]
				i++
			}
		case "--body":
			if i+1 < len(args) {
				body = args[i+1]
				i++
			}
		}
	}

	if from == "" {
		return errors.New("missing required flag: --from")
	}
	if to == "" {
		return errors.New("missing required flag: --to")
	}

	p, _ := csuite.ParseInboxPriority(priority)
	if p == "" {
		p = csuite.PriorityNormal
	}
	t, _ := csuite.ParseInboxMessageType(msgType)
	if t == "" {
		t = csuite.MessageTypeStatus
	}

	msg := csuite.CsuiteInboxMessage{
		ID:        uuid.New(),
		FromAgent: from,
		ToAgent:   to,
		Subject:   subject,
		Priority:  p,
		Type:      t,
		Body:      body,
		Archived:  false,
	}

	return db.Create(&msg).Error
}

